function attack(kind){if(scene!=='play'||player.stun>0)return;const now=performance.now()/1000;if(now-lastAction<(kind==='heavy'?.58:.34))return;lastAction=now;player.attack=kind==='heavy'?.43:.28;player.facing=1;const target=enemies.filter(e=>e.alive).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x))[0];if(!target||Math.abs(target.x-player.x)>145){say('Step a little closer');return}if(target.stun>0||target.guard<=0){const dmg=kind==='heavy'?34:22;target.hp=Math.max(0,target.hp-dmg);target.stun=kind==='heavy'?.78:.48;target.x=clamp(target.x+24,390,860);shake=kind==='heavy'?7:4;burst(target.x-10,348,kind==='heavy'?'#f3bf80':'#c6ead9');if(target.hp<=0){target.alive=false;burst(target.x,360,'#a6e2ca',18);say('A way forward!')}else say(kind==='heavy'?'Strong kick!':'Nice opening!')}else{say('Wait for an opening');}}
function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*190,vy:-30-Math.random()*130,life:.45+Math.random()*.38,color,r:2+Math.random()*3});}
function setAction(name,on){if(name==='left'||name==='right')keys[name]=on;else if(name==='block'){keys.block=on;if(on&&scene==='play')player.guard=.2}else if(on){if(name==='light')attack('light');else if(name==='heavy')attack('heavy')}}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright',' ','arrowup'].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')keys.left=true;if(k==='d'||k==='arrowright')keys.right=true;if(k==='j'||k==='z')attack('light');if(k==='k'||k==='x')attack('heavy');if(k===' '||k==='arrowup'){if(scene==='play')player.guard=.18}});
document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')keys.left=false;if(k==='d'||k==='arrowright')keys.right=false;if(k===' '||k==='arrowup')keys.block=false;});
document.querySelectorAll('[data-action]').forEach(button=>{const action=button.dataset.action;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);setAction(action,true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,e=>{if(action==='left'||action==='right')setAction(action,false)});});

